const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const state = { user: null, route: 'dashboard', page: 1, cache: {} };
const fmt = new Intl.NumberFormat('fr-FR');
const money = v => `${fmt.format(Number(v || 0))} FCFA`;
const dateFr = v => v ? new Date(v).toLocaleDateString('fr-FR') : '—';
const dtFr = v => v ? new Date(v).toLocaleString('fr-FR', { dateStyle: 'short', timeStyle: 'short' }) : '—';
const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusLabels = {received:'Reçu',waiting:'En attente',in_progress:'En cours',review:'À vérifier',completed:'Terminé',ready:'Prêt',delivered:'Livré',cancelled:'Annulé',active:'Actif',late:'En retard',paid:'Payé',draft:'Brouillon',final:'Final',archived:'Archivé',completed_sale:'Terminée'};
const roleLabels = {super_admin:'Super Administrateur',admin:'Administrateur',director:'Direction',manager:'Responsable',cashier:'Caissier',office_agent:'Agent bureautique',mobile_money_agent:'Agent Mobile Money',sales_agent:'Agent commercial',stock_manager:'Gestionnaire stock',accountant:'Comptable',employee:'Employé',readonly:'Lecture seule'};
const navGroups = [
  ['PRINCIPAL', [['dashboard','▦','Tableau de bord']]],
  ['TRAVAIL', [['clients','♙','Clients'],['jobs','▣','Travaux'],['documents','▤','Documents'],['services','⌘','Services & tarifs']]],
  ['COMMERCIAL', [['sales','▧','Ventes'],['products','◇','Stock & produits'],['suppliers','◫','Fournisseurs']]],
  ['FINANCE', [['cash','₣','Caisse'],['mobile','◉','Mobile Money'],['credits','◎','Crédits'],['expenses','↘','Dépenses']]],
  ['GESTION', [['employees','♟','Employés'],['reports','⌁','Rapports']]],
  ['SYSTÈME', [['audit','≡','Journal d’activité'],['settings','⚙','Paramètres'],['health','●','Santé système']]]
];

async function api(path, options = {}) {
  const opts = { credentials: 'same-origin', ...options };
  opts.headers = { ...(options.body ? {'content-type':'application/json'} : {}), ...(options.headers || {}) };
  const res = await fetch(`/api/${path}`, opts);
  const raw = await res.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch {}
  if (!res.ok || data.ok === false) {
    if (res.status === 401 && state.user) { state.user = null; showAuth(); }
    const plain = raw && !raw.trim().startsWith('<') ? raw.trim().replace(/\s+/g,' ').slice(0,420) : '';
    const err = new Error(data.error || plain || `Erreur HTTP ${res.status}`);
    err.status = res.status;
    err.code = data.code || '';
    err.ray = res.headers.get('cf-ray') || '';
    err.version = res.headers.get('x-msws-version') || data.version || '';
    throw err;
  }
  return data;
}
function toast(msg, type = 'ok') { const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=msg; $('#toast-root').append(el); setTimeout(()=>el.remove(),4200); }
function setHead(title, subtitle='', actions='') { $('#page-title').textContent=title; $('#page-subtitle').textContent=subtitle; $('#page-actions').innerHTML=actions; }
function showLoading(){ $('#page').innerHTML='<div class="card empty">Chargement sécurisé des données…</div>'; }
function empty(msg='Aucune donnée à afficher.'){ return `<div class="empty">${esc(msg)}</div>`; }
function badge(s){ const cls=['cancelled','late'].includes(s)?'danger':['waiting','review'].includes(s)?'warn':['paid','active','completed','ready','delivered','final'].includes(s)?'ok':'gold'; return `<span class="badge ${cls}">${esc(statusLabels[s]||s||'—')}</span>`; }
function table(headers, rows, emptyMsg='Aucun enregistrement.'){ if(!rows.length) return `<div class="table-card">${empty(emptyMsg)}</div>`; return `<div class="table-card"><div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div></div>`; }
function modal(title, html){ $('#modal-title').textContent=title; $('#modal-body').innerHTML=html; $('#modal').showModal(); }
function closeModal(){ $('#modal').close(); $('#modal-body').innerHTML=''; }
function formActions(label='Enregistrer'){ return `<div class="modal-actions"><button type="button" class="btn" data-close>Annuler</button><button type="submit" class="btn primary">${esc(label)}</button></div>`; }
function value(fd,key){ const v=fd.get(key); return typeof v==='string'?v.trim():v; }
function objFromForm(form){ return Object.fromEntries(new FormData(form).entries()); }
function clientName(x){ return [x.client_last_name||x.last_name,x.client_first_name||x.first_name].filter(Boolean).join(' ')||'Client comptoir'; }
function initials(name){ return String(name||'MS').split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(); }
function formField(label,name,type='text',extra=''){ return `<label>${label}<input name="${name}" type="${type}" ${extra}></label>`; }
function selectField(label,name,items,valueKey='id',labelFn=x=>x.name,extra=''){ return `<label>${label}<select name="${name}" ${extra}><option value="">— Sélectionner —</option>${items.map(x=>`<option value="${esc(x[valueKey])}">${esc(labelFn(x))}</option>`).join('')}</select></label>`; }
function actionButton(text, action, cls='btn compact'){ return `<button class="${cls}" data-action="${action}">${text}</button>`; }

async function init(){
  bindStatic();
  try { const me=await api('auth/me'); state.user=me.user; showApp(); navigate(location.hash.slice(1)||'dashboard'); }
  catch { await showAuth(); }
}
async function prepareBootstrapSchema(token, button, diag){
  let cursor = 0, total = 1, guard = 0;
  while (cursor < total && guard++ < 200) {
    if (button) button.textContent = total > 1 ? `Préparation D1… ${Math.min(cursor,total)}/${total}` : 'Préparation de la base D1…';
    const d = await api('bootstrap/schema', {method:'POST', body:JSON.stringify({bootstrap_token:token, cursor})});
    total = Math.max(1, Number(d.total || 1));
    cursor = Number(d.next_cursor || 0);
    if (diag) diag.innerHTML = `<div class="install-checks"><span class="ok">✓ D1 SYSTEME_DB</span><span class="ok">✓ BOOTSTRAP_TOKEN</span><span class="ok">Préparation ${Math.min(cursor,total)}/${total}</span></div><small>Installation progressive MSWS v${esc(d.version||'1.3.0')} — aucune grosse migration n’est exécutée dans une seule requête.</small>`;
    if (d.done) return d;
    if (cursor >= total && !d.database_initialized) throw Object.assign(new Error(`Préparation D1 incomplète. Tables manquantes : ${(d.missing_tables||[]).join(', ')}`), {code:'D1_SCHEMA_NOT_READY'});
  }
  throw Object.assign(new Error('La préparation D1 a dépassé le nombre maximal d’étapes autorisé.'), {code:'D1_SCHEMA_LOOP_GUARD'});
}

function bindStatic(){
  $('#modal-close').onclick=closeModal;
  $('#modal').addEventListener('click', e=>{ if(e.target===$('#modal')) closeModal(); });
  document.addEventListener('click',e=>{ if(e.target.matches('[data-close]')) closeModal(); });
  $('#login-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('auth/login',{method:'POST',body:JSON.stringify({email:$('#login-email').value,password:$('#login-password').value})});state.user=d.user;showApp();navigate('dashboard');}catch(err){toast(err.message,'error')}};
  $('#bootstrap-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter||e.target.querySelector('button[type="submit"]');const diag=$('#bootstrap-diagnostics');const token=$('#boot-token').value;if(btn){btn.disabled=true;btn.textContent='Préparation de la base D1…';}try{await prepareBootstrapSchema(token,btn,diag);if(btn)btn.textContent='Création du Super Administrateur…';const d=await api('bootstrap',{method:'POST',body:JSON.stringify({name:$('#boot-name').value,email:$('#boot-email').value,password:$('#boot-password').value,bootstrap_token:token})});state.user=d.user;showApp();navigate('dashboard');toast('Système initialisé avec succès.');}catch(err){if(diag){diag.innerHTML=`<div class="install-error"><b>Échec de l’initialisation</b><span>${esc(err.message)}</span>${err.code?`<small>Code : ${esc(err.code)}</small>`:''}${err.ray?`<small>Cloudflare Ray ID : ${esc(err.ray)}</small>`:''}${err.version?`<small>API MSWS : v${esc(err.version)}</small>`:''}</div>`;}toast(err.message,'error');if(err.code==='BOOTSTRAP_SESSION_FAILED') setTimeout(()=>location.reload(),1600);}finally{if(btn){btn.disabled=false;btn.textContent='Initialiser le système';}}};
  $('#logout-btn').onclick=async()=>{try{await api('auth/logout',{method:'POST'});}catch{} state.user=null;showAuth();};
  $('#user-btn').onclick=()=>$('#user-dropdown').hidden=!$('#user-dropdown').hidden;
  $('#refresh-btn').onclick=()=>renderRoute();
  $('#quick-btn').onclick=showQuick;
  $('#menu-btn').onclick=()=>$('#sidebar').classList.toggle('open');
  let searchTimer;
  $('#global-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(globalSearch,260)});
  document.addEventListener('click',e=>{ if(!e.target.closest('.global-search-wrap')) $('#search-results').hidden=true; });
  window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'dashboard'));
}
async function showAuth(){ $('#app').hidden=true; $('#auth-view').hidden=false; try{const s=await api('bootstrap/status'); $('#bootstrap-panel').hidden=s.initialized; $('#login-panel').hidden=!s.initialized; const diag=$('#bootstrap-diagnostics'); const submit=$('#bootstrap-form button[type="submit"]'); if(diag&&!s.initialized){const checks=[['D1 SYSTEME_DB',s.d1_bound!==false,true],['KV SYSTEME_KV',s.kv_bound!==false,false],['BOOTSTRAP_TOKEN',!!s.bootstrap_secret_configured,true]];diag.innerHTML=`<div class="install-checks">${checks.map(([label,ok,required])=>`<span class="${ok?'ok':required?'bad':'warn'}">${ok?'✓':required?'✕':'!'} ${esc(label)}${!required?' (cache)':''}</span>`).join('')}</div>${!s.database_initialized&&s.d1_bound!==false?`<small>MSWS v${esc(s.version||'1.3.0')} — le schéma D1 sera préparé progressivement lors de la validation. Chaque étape utilise une requête Cloudflare courte.</small>`:''}`;if(submit)submit.disabled=checks.some(([,ok,required])=>required&&!ok);} if(!s.initialized&&s.d1_bound===false) toast('Binding D1 SYSTEME_DB absent dans Cloudflare.','error'); else if(!s.initialized&&!s.bootstrap_secret_configured) toast('Configurez le secret BOOTSTRAP_TOKEN dans Cloudflare avant l’initialisation.','error'); else if(!s.initialized&&!s.database_initialized) toast('Base D1 détectée : les tables seront créées automatiquement lors de l’initialisation.'); else if(!s.initialized&&s.kv_bound===false) toast('KV n’est pas lié : le système utilisera D1 pour la session, mais ajoutez SYSTEME_KV ensuite.','error');}catch(err){toast(err.message||'Impossible d’accéder à la configuration Cloudflare.','error');} }
function showApp(){ $('#auth-view').hidden=true; $('#app').hidden=false; $('#user-name').textContent=state.user.name; $('#user-role').textContent=roleLabels[state.user.role]||state.user.role; $('#user-avatar').textContent=initials(state.user.name); renderNav(); checkHealth(); }
function renderNav(){ $('#nav').innerHTML=navGroups.map(([g,items])=>`<div class="nav-group">${g}</div>${items.map(([r,i,l])=>`<button class="nav-item ${state.route===r?'active':''}" data-route="${r}"><span class="nav-icon">${i}</span>${l}</button>`).join('')}`).join(''); $$('#nav [data-route]').forEach(b=>b.onclick=()=>navigate(b.dataset.route)); }
function navigate(route){ const known=new Set(navGroups.flatMap(g=>g[1].map(x=>x[0]))); state.route=known.has(route)?route:'dashboard'; state.page=1; if(location.hash.slice(1)!==state.route) history.replaceState(null,'',`#${state.route}`); renderNav(); $('#sidebar').classList.remove('open'); renderRoute(); }
async function renderRoute(){ showLoading(); const map={dashboard:renderDashboard,clients:renderClients,jobs:renderJobs,documents:renderDocuments,services:renderServices,sales:renderSales,products:renderProducts,suppliers:renderSuppliers,cash:renderCash,mobile:renderMobile,credits:renderCredits,expenses:renderExpenses,employees:renderEmployees,reports:renderReports,audit:renderAudit,settings:renderSettings,health:renderHealth}; try{await (map[state.route]||renderDashboard)();}catch(err){$('#page').innerHTML=`<div class="card empty"><b>Impossible de charger cette section.</b><br><span class="muted">${esc(err.message)}</span><br><br><button class="btn" id="retry">Réessayer</button></div>`; $('#retry')?.addEventListener('click',renderRoute);} }
async function checkHealth(){ try{const h=await api('health');$('#system-status').textContent=h.database==='connected'?'Cloud connecté':'État inconnu';}catch{$('#system-status').textContent='Connexion à vérifier';} }
async function globalSearch(){ const q=$('#global-search').value.trim(),box=$('#search-results'); if(q.length<2){box.hidden=true;return;} try{const d=await api(`search?q=${encodeURIComponent(q)}`); box.innerHTML=d.results.length?d.results.slice(0,20).map(r=>`<div class="search-row"><div><b>${esc(r.title)}</b><small>${esc(r.reference)} • ${esc(r.subtitle||'')}</small></div><span class="badge gold">${esc(r.type)}</span></div>`).join(''):empty('Aucun résultat.'); box.hidden=false;}catch{box.hidden=true;} }

async function renderDashboard(){
  setHead('Tableau de bord','Vue consolidée de l’activité de MEGA SERVICES SARL U.',actionButton('＋ Nouveau travail','new-job','btn primary compact'));
  const d=await api('dashboard');
  $('#page').innerHTML=`
    <div class="grid cols-4">
      <div class="card metric dark"><div class="label">Chiffre encaissé aujourd’hui</div><div class="value">${money(d.today.cash_income)}</div><div class="sub">Tous moyens de paiement</div></div>
      <div class="card metric"><div class="label">Clients servis aujourd’hui</div><div class="value">${fmt.format(d.today.clients)}</div><div class="sub">Nouveaux dossiers clients</div></div>
      <div class="card metric"><div class="label">Travaux enregistrés</div><div class="value">${fmt.format(d.today.jobs)}</div><div class="sub">Valeur ${money(d.today.job_total)}</div></div>
      <div class="card metric"><div class="label">Résultat de trésorerie estimé</div><div class="value">${money(d.today.estimated_result)}</div><div class="sub">Entrées - sorties du jour</div></div>
    </div>
    <div class="grid cols-2" style="margin-top:16px">
      <div class="card"><div class="section-title" style="margin-top:0"><h2>Trésorerie par caisse</h2><span class="badge gold">Temps réel</span></div><div class="account-list">${d.accounts.map(a=>`<div class="account-pill"><small>${esc(a.name)}</small><b>${money(a.balance)}</b></div>`).join('')}</div></div>
      <div class="card"><div class="section-title" style="margin-top:0"><h2>Crédits & créances</h2></div><div class="grid cols-2"><div class="metric"><div class="label">Crédits actifs</div><div class="value">${fmt.format(d.credits.active_count)}</div></div><div class="metric"><div class="label">Reste à recouvrer</div><div class="value">${money(d.credits.balance)}</div></div></div></div>
    </div>
    <div class="grid cols-2" style="margin-top:16px">
      <div class="card"><div class="section-title" style="margin-top:0"><h2>État des travaux</h2></div><div class="alert-list">${d.job_states.length?d.job_states.map(x=>`<div class="alert-row"><span>${badge(x.status)}</span><b>${fmt.format(x.count)}</b></div>`).join(''):empty('Aucun travail enregistré aujourd’hui.')}</div></div>
      <div class="card"><div class="section-title" style="margin-top:0"><h2>Alertes stock</h2></div><div class="alert-list">${d.low_stock.length?d.low_stock.map(x=>`<div class="alert-row"><span><b>${esc(x.name)}</b><small class="row-sub">${esc(x.code)}</small></span><span class="badge danger">${fmt.format(x.stock_quantity)} restant</span></div>`).join(''):empty('Aucune alerte de stock.')}</div></div>
    </div>`;
  $('#page-actions [data-action="new-job"]').onclick=openJobForm;
}

async function renderClients(){
  setHead('Clients','Fichier client unique et historique transversal.',actionButton('＋ Nouveau client','new-client','btn primary compact'));
  const d=await api(`clients?page=${state.page}&size=25`);
  const rows=d.items.map(c=>`<tr><td><span class="row-title">${esc(c.last_name)} ${esc(c.first_name||'')}</span><span class="row-sub">${esc(c.reference)}</span></td><td>${esc(c.phone||'—')}</td><td>${esc(c.whatsapp||'—')}</td><td>${esc(c.city||'—')}</td><td>${dateFr(c.created_at)}</td><td><button class="btn compact" data-client="${c.id}">Ouvrir</button></td></tr>`);
  $('#page').innerHTML=`<div class="toolbar"><input class="search-mini" id="client-q" placeholder="Nom, téléphone, référence…"><button class="btn compact" id="client-search">Rechercher</button></div>${table(['Client','Téléphone','WhatsApp','Ville','Créé le',''],rows,'Aucun client enregistré.')}${pager(d)}`;
  $('#page-actions [data-action="new-client"]').onclick=openClientForm;
  $$('.btn[data-client]').forEach(b=>b.onclick=()=>showClient(b.dataset.client));
  $('#client-search').onclick=async()=>{const q=$('#client-q').value.trim();const r=await api(`clients?size=50&q=${encodeURIComponent(q)}`);$('#page').querySelector('.table-card').outerHTML=table(['Client','Téléphone','WhatsApp','Ville','Créé le',''],r.items.map(c=>`<tr><td><span class="row-title">${esc(c.last_name)} ${esc(c.first_name||'')}</span><span class="row-sub">${esc(c.reference)}</span></td><td>${esc(c.phone||'—')}</td><td>${esc(c.whatsapp||'—')}</td><td>${esc(c.city||'—')}</td><td>${dateFr(c.created_at)}</td><td><button class="btn compact" data-client="${c.id}">Ouvrir</button></td></tr>`)); $$('.btn[data-client]').forEach(b=>b.onclick=()=>showClient(b.dataset.client));};
}
function pager(d){ if(!d.total||d.total<=d.size) return ''; const pages=Math.ceil(d.total/d.size); return `<div class="pagination"><button id="prev-page" ${d.page<=1?'disabled':''}>← Précédent</button><span>Page ${d.page} / ${pages} • ${fmt.format(d.total)} éléments</span><button id="next-page" ${d.page>=pages?'disabled':''}>Suivant →</button></div>`; }
function bindPager(){ $('#prev-page')?.addEventListener('click',()=>{state.page=Math.max(1,state.page-1);renderRoute()});$('#next-page')?.addEventListener('click',()=>{state.page++;renderRoute()}); }
async function openClientForm(){ modal('Nouveau client',`<form id="client-form"><div class="form-grid">${formField('Civilité','civility')}${formField('Nom *','last_name','text','required')}${formField('Prénoms','first_name')}${formField('Téléphone','phone','tel')}${formField('WhatsApp','whatsapp','tel')}${formField('Email','email','email')}${formField('Profession','profession')}${formField('Entreprise','company')}${formField('Ville','city')}${formField('Commune','commune')}${formField('Quartier','district')}${formField('Nationalité','nationality')}<label class="full">Observation<textarea name="notes"></textarea></label></div>${formActions('Créer le client')}</form>`); $('#client-form').onsubmit=async e=>{e.preventDefault();try{const b=objFromForm(e.target);const d=await api('clients',{method:'POST',body:JSON.stringify(b)});closeModal();toast(`Client créé : ${d.reference}`);renderRoute();}catch(err){toast(err.message,'error')}}; }
async function showClient(id){ try{const d=await api(`clients/${id}`),c=d.client; modal(`${c.last_name} ${c.first_name||''}`,`<div class="grid cols-3"><div class="card soft"><small>Référence</small><b class="row-sub">${esc(c.reference)}</b></div><div class="card soft"><small>Téléphone</small><b class="row-sub">${esc(c.phone||'—')}</b></div><div class="card soft"><small>WhatsApp</small><b class="row-sub">${esc(c.whatsapp||'—')}</b></div></div><div class="section-title"><h2>Historique des travaux</h2></div>${table(['Référence','Travail','Statut','Total','Reste'],d.history.jobs.map(j=>`<tr><td>${esc(j.reference)}</td><td>${esc(j.title)}</td><td>${badge(j.status)}</td><td class="money">${money(j.total)}</td><td class="money">${money(j.balance)}</td></tr>`),'Aucun travail.')}<div class="section-title"><h2>Crédits</h2></div>${table(['Référence','Total','Payé','Reste','Statut'],d.history.credits.map(x=>`<tr><td>${esc(x.reference)}</td><td class="money">${money(x.total_due)}</td><td class="money">${money(x.amount_paid)}</td><td class="money">${money(x.balance)}</td><td>${badge(x.status)}</td></tr>`),'Aucun crédit.')}`);}catch(err){toast(err.message,'error')} }

async function lookups(){ const [clients,services,employees,accounts,products,suppliers]=await Promise.all([api('clients?size=100'),api('services'),api('employees'),api('cash/accounts'),api('products?size=100'),api('suppliers')]); return {clients:clients.items,services:services.items,employees:employees.items,accounts:accounts.items,products:products.items,suppliers:suppliers.items}; }
async function renderJobs(){ setHead('Travaux','Suivi complet des demandes clients, de la réception à la livraison.',actionButton('＋ Nouveau travail','new-job','btn primary compact')); const d=await api(`jobs?page=${state.page}&size=25`); $('#page').innerHTML=table(['Référence','Client','Travail','Statut','Priorité','Total','Payé','Reste',''],d.items.map(j=>`<tr><td><span class="row-title">${esc(j.reference)}</span><span class="row-sub">${dateFr(j.created_at)}</span></td><td>${esc(clientName(j))}</td><td>${esc(j.title)}</td><td>${badge(j.status)}</td><td>${esc(j.priority)}</td><td class="money">${money(j.total)}</td><td class="money">${money(j.paid)}</td><td class="money">${money(j.balance)}</td><td>${j.balance>0?`<button class="btn compact" data-payjob="${j.id}">Payer</button>`:''} <button class="btn compact" data-jobstatus="${j.id}" data-status="${j.status}">Statut</button></td></tr>`),'Aucun travail enregistré.')+pager(d); $('#page-actions [data-action="new-job"]').onclick=openJobForm; $$('[data-payjob]').forEach(b=>b.onclick=()=>openJobPayment(b.dataset.payjob)); $$('[data-jobstatus]').forEach(b=>b.onclick=()=>openJobStatus(b.dataset.jobstatus,b.dataset.status)); bindPager(); }
async function openJobForm(){ try{const l=await lookups(); modal('Nouveau travail',`<form id="job-form"><div class="form-grid">${selectField('Client','client_id',l.clients,'id',x=>`${x.last_name} ${x.first_name||''} — ${x.phone||x.reference}`)}${selectField('Service','service_id',l.services,'id',x=>`${x.name} — ${money(x.price)}`)}${formField('Intitulé du travail *','title','text','required')}${formField('Quantité','quantity','number','min="0.01" step="0.01" value="1"')}${formField('Prix unitaire','unit_price','number','min="0" value="0"')}${formField('Remise','discount','number','min="0" value="0"')}${formField('Paiement immédiat','paid','number','min="0" value="0"')}${selectField('Caisse','cash_account_id',l.accounts,'id',x=>`${x.name} — ${money(x.balance)}`)}<label>Priorité<select name="priority"><option value="normal">Normale</option><option value="urgent">Urgente</option><option value="very_urgent">Très urgente</option></select></label>${selectField('Agent assigné','assigned_employee_id',l.employees,'id',x=>`${x.last_name} ${x.first_name}`)}${formField('Échéance','due_at','datetime-local')}<label class="full">Détail<textarea name="description"></textarea></label></div><div class="card soft" id="job-total" style="margin-top:14px">Total estimé : <b>0 FCFA</b></div>${formActions('Enregistrer le travail')}</form>`); const form=$('#job-form'),srv=form.elements.service_id; srv.onchange=()=>{const s=l.services.find(x=>x.id===srv.value);if(s)form.elements.unit_price.value=s.price;calc()}; const calc=()=>{const total=Math.max(0,(Number(form.elements.quantity.value||1)*Number(form.elements.unit_price.value||0))-Number(form.elements.discount.value||0));$('#job-total b').textContent=money(total)}; ['quantity','unit_price','discount'].forEach(n=>form.elements[n].oninput=calc); form.onsubmit=async e=>{e.preventDefault();try{const d=await api('jobs',{method:'POST',body:JSON.stringify(objFromForm(form))});closeModal();toast(`Travail enregistré : ${d.reference}`);renderRoute();}catch(err){toast(err.message,'error')}};}catch(err){toast(err.message,'error')} }
async function openJobPayment(id){const a=await api('cash/accounts');modal('Encaisser un paiement',`<form id="pay-job"><div class="form-grid">${formField('Montant *','amount','number','min="1" required')}${selectField('Caisse','cash_account_id',a.items,'id',x=>`${x.name} — ${money(x.balance)}`)}<label>Moyen de paiement<select name="payment_method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN Money</option><option value="moov_money">Moov Money</option><option value="bank">Banque</option></select></label></div>${formActions('Encaisser')}</form>`);$('#pay-job').onsubmit=async e=>{e.preventDefault();try{await api(`jobs/${id}/payment`,{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Paiement enregistré et reçu généré.');renderRoute();}catch(err){toast(err.message,'error')}};}
function openJobStatus(id,current){modal('Modifier le statut',`<form id="job-status"><label>Statut<select name="status">${[['received','Reçu'],['waiting','En attente'],['in_progress','En cours'],['review','À vérifier'],['completed','Terminé'],['ready','Prêt'],['delivered','Livré'],['cancelled','Annulé']].map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('')}</select></label>${formActions('Mettre à jour')}</form>`);$('#job-status').onsubmit=async e=>{e.preventDefault();try{await api(`jobs/${id}`,{method:'PUT',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Statut mis à jour.');renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderDocuments(){ setHead('Documents','Atelier documentaire avec historique de versions.',actionButton('＋ Nouveau document','new-doc','btn primary compact'));const d=await api(`documents?page=${state.page}&size=25`);$('#page').innerHTML=table(['Référence','Titre','Client','Type','Version','Statut','Modifié',''],d.items.map(x=>`<tr><td>${esc(x.reference)}</td><td class="row-title">${esc(x.title)}</td><td>${esc(clientName(x))}</td><td>${esc(x.document_type)}</td><td>v${x.version}</td><td>${badge(x.status)}</td><td>${dtFr(x.updated_at)}</td><td><button class="btn compact" data-doc="${x.id}">Ouvrir</button></td></tr>`),'Aucun document.')+pager(d);$('#page-actions [data-action="new-doc"]').onclick=()=>openDocumentEditor();$$('[data-doc]').forEach(b=>b.onclick=()=>openDocumentEditor(b.dataset.doc));bindPager();}
async function openDocumentEditor(id=null){try{const clients=(await api('clients?size=100')).items;let d=null;if(id)d=(await api(`documents/${id}`)).document;modal(id?'Modifier le document':'Nouveau document',`<form id="doc-form"><div class="form-grid">${selectField('Client','client_id',clients,'id',x=>`${x.last_name} ${x.first_name||''}`)}${formField('Type de document *','document_type','text','required placeholder="Courrier, CV, demande…"')}${formField('Titre *','title','text','required class="full"')}<label>Statut<select name="status"><option value="draft">Brouillon</option><option value="final">Final</option><option value="archived">Archivé</option></select></label></div><div class="section-title"><h2>Contenu du document</h2><div><button type="button" class="btn compact" id="insert-letter">Modèle courrier</button> <button type="button" class="btn compact" id="print-doc">Imprimer</button></div></div><div id="doc-editor" class="doc-editor" contenteditable="true"></div><p class="muted">L’assistant IA est prévu comme intégration optionnelle. Cette version conserve la rédaction et les modèles dans D1 sans exposer de clé API.</p>${formActions(id?'Enregistrer une nouvelle version':'Créer le document')}</form>`);const f=$('#doc-form'),ed=$('#doc-editor');if(d){f.elements.client_id.value=d.client_id||'';f.elements.document_type.value=d.document_type;f.elements.title.value=d.title;f.elements.status.value=d.status;ed.innerHTML=d.body_html||'';}$('#insert-letter').onclick=()=>{ed.innerHTML=`<p><strong>MEGA SERVICES SARL U</strong></p><p>Diabo, le ${new Date().toLocaleDateString('fr-FR')}</p><p><br></p><p><strong>Objet : </strong></p><p><br></p><p>Monsieur / Madame,</p><p><br></p><p>J’ai l’honneur de...</p><p><br></p><p>Veuillez agréer l’expression de ma considération distinguée.</p>`};$('#print-doc').onclick=()=>printHtml(f.elements.title.value||'Document',ed.innerHTML);f.onsubmit=async e=>{e.preventDefault();const b=objFromForm(f);b.body_html=ed.innerHTML;try{if(id)await api(`documents/${id}`,{method:'PUT',body:JSON.stringify(b)});else await api('documents',{method:'POST',body:JSON.stringify(b)});closeModal();toast(id?'Nouvelle version enregistrée.':'Document créé.');renderRoute();}catch(err){toast(err.message,'error')}};}catch(err){toast(err.message,'error')}}
function printHtml(title,html){const w=window.open('','_blank');w.document.write(`<!doctype html><html><head><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;max-width:800px;margin:40px auto;line-height:1.55;font-size:14px} @media print{body{margin:20mm}}</style></head><body>${html}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),200);}

async function renderServices(){setHead('Services & tarifs','Catalogue central des prestations MEGA SERVICES.',actionButton('＋ Nouveau service','new-service','btn primary compact'));const d=await api('services');$('#page').innerHTML=table(['Code','Catégorie','Service','Unité','Prix','Coût','Marge'],d.items.map(s=>`<tr><td>${esc(s.code)}</td><td>${esc(s.category_name||'—')}</td><td class="row-title">${esc(s.name)}</td><td>${esc(s.unit)}</td><td class="money">${money(s.price)}</td><td class="money">${money(s.cost)}</td><td class="money">${money(Number(s.price)-Number(s.cost))}</td></tr>`),'Aucun service.');$('#page-actions [data-action="new-service"]').onclick=()=>openServiceForm(d.categories);}
function openServiceForm(cats){modal('Nouveau service',`<form id="service-form"><div class="form-grid">${formField('Code *','code','text','required')}${formField('Nom *','name','text','required')}${selectField('Catégorie','category_id',cats)}${formField('Unité','unit','text','value="unité"')}${formField('Prix de vente','price','number','min="0" value="0"')}${formField('Coût','cost','number','min="0" value="0"')}<label class="full">Description<textarea name="description"></textarea></label></div>${formActions('Créer')}</form>`);$('#service-form').onsubmit=async e=>{e.preventDefault();try{await api('services',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Service ajouté.');renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderCash(){setHead('Caisse','Tous les mouvements financiers et soldes consolidés.',`${actionButton('＋ Mouvement','new-cash','btn primary compact')} ${actionButton('Clôturer la caisse','close-cash','btn compact')}`);const [a,t]=await Promise.all([api('cash/accounts'),api(`cash/transactions?page=${state.page}&size=30`)]);$('#page').innerHTML=`<div class="account-list">${a.items.map(x=>`<div class="account-pill"><small>${esc(x.name)}</small><b>${money(x.balance)}</b><span class="row-sub">${esc(x.code)}</span></div>`).join('')}</div><div class="section-title"><h2>Derniers mouvements</h2></div>${table(['Référence','Date','Caisse','Type','Description','Montant'],t.items.map(x=>`<tr><td>${esc(x.reference)}</td><td>${dtFr(x.created_at)}</td><td>${esc(x.account_name)}</td><td>${esc(x.type)}</td><td>${esc(x.description)}</td><td class="money">${x.type==='expense'||x.type==='transfer_out'?'-':'+'}${money(x.amount)}</td></tr>`),'Aucun mouvement.')}${pager(t)}`;$('#page-actions [data-action="new-cash"]').onclick=()=>openCashForm(a.items);$('#page-actions [data-action="close-cash"]').onclick=()=>openClosure(a.items);bindPager();}
function openCashForm(accounts){modal('Nouveau mouvement de caisse',`<form id="cash-form"><div class="form-grid">${selectField('Caisse *','account_id',accounts,'id',x=>`${x.name} — ${money(x.balance)}`,'required')}<label>Type<select name="type"><option value="income">Entrée</option><option value="expense">Sortie</option><option value="correction">Correction</option><option value="transfer_in">Transfert entrant</option><option value="transfer_out">Transfert sortant</option></select></label>${formField('Catégorie','category')}${formField('Montant *','amount','number','min="1" required')}<label class="full">Description<textarea name="description" required></textarea></label></div>${formActions('Enregistrer')}</form>`);$('#cash-form').onsubmit=async e=>{e.preventDefault();try{await api('cash/transactions',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Mouvement enregistré.');renderRoute();}catch(err){toast(err.message,'error')}};}
function openClosure(accounts){modal('Clôture de caisse',`<form id="closure-form"><div class="form-grid">${selectField('Caisse','account_id',accounts,'id',x=>`${x.name} — théorique ${money(x.balance)}`,'required')}${formField('Date','closure_date','date',`value="${new Date().toISOString().slice(0,10)}"`)}${formField('Solde réel compté *','actual_balance','number','required')}<label class="full">Justification d’un éventuel écart<textarea name="justification"></textarea></label></div>${formActions('Clôturer')}</form>`);$('#closure-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('cash/closure',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Clôture enregistrée. Écart : ${money(d.difference)}`,d.difference===0?'ok':'error');renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderMobile(){setHead('Mobile Money','Wave, Orange Money, MTN Money, Moov Money et mouvements de liquidité.',actionButton('＋ Nouvelle opération','new-mm','btn primary compact'));const d=await api(`mobile-money?page=${state.page}&size=30`);$('#page').innerHTML=table(['Référence','Date','Opérateur','Opération','Téléphone','Montant','Frais','Commission'],d.items.map(x=>`<tr><td>${esc(x.reference)}</td><td>${dtFr(x.created_at)}</td><td class="row-title">${esc(x.operator)}</td><td>${esc(x.operation_type)}</td><td>${esc(x.customer_phone||'—')}</td><td class="money">${money(x.amount)}</td><td class="money">${money(x.fees)}</td><td class="money">${money(x.commission)}</td></tr>`),'Aucune opération Mobile Money.')+pager(d);$('#page-actions [data-action="new-mm"]').onclick=openMobileForm;bindPager();}
async function openMobileForm(){const l=await lookups();modal('Nouvelle opération Mobile Money',`<form id="mm-form"><div class="form-grid"><label>Opérateur<select name="operator"><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN Money</option><option value="moov_money">Moov Money</option><option value="other">Autre</option></select></label><label>Opération<select name="operation_type"><option value="deposit">Dépôt client</option><option value="withdrawal">Retrait client</option><option value="transfer">Transfert</option><option value="payment">Paiement</option><option value="commission">Commission</option><option value="float_in">Approvisionnement float</option><option value="float_out">Retrait de float</option></select></label>${selectField('Client','client_id',l.clients,'id',x=>`${x.last_name} ${x.first_name||''} — ${x.phone||''}`)}${formField('Téléphone opération','customer_phone','tel')}${formField('Montant *','amount','number','min="0" required')}${formField('Frais','fees','number','min="0" value="0"')}${formField('Commission','commission','number','min="0" value="0"')}<label class="full">Note<textarea name="note"></textarea></label></div>${formActions('Valider l’opération')}</form>`);$('#mm-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('mobile-money',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Opération enregistrée : ${d.reference}`);renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderProducts(){setHead('Stock & produits','Inventaire, seuils d’alerte, prix d’achat et de vente.',actionButton('＋ Nouveau produit','new-product','btn primary compact'));const d=await api(`products?page=${state.page}&size=30`);$('#page').innerHTML=table(['Code','Produit','Stock','Seuil','Achat','Vente','Marge',''],d.items.map(p=>`<tr><td>${esc(p.code)}</td><td class="row-title">${esc(p.name)}</td><td class="money">${fmt.format(p.stock_quantity)} ${esc(p.unit)}</td><td>${fmt.format(p.min_stock)}</td><td class="money">${money(p.purchase_price)}</td><td class="money">${money(p.sale_price)}</td><td class="money">${money(p.margin)}</td><td><button class="btn compact" data-stock="${p.id}">Mouvement</button></td></tr>`),'Aucun produit.')+pager(d);$('#page-actions [data-action="new-product"]').onclick=openProductForm;$$('[data-stock]').forEach(b=>b.onclick=()=>openStockAdjust(b.dataset.stock));bindPager();}
async function openProductForm(){const s=(await api('suppliers')).items;modal('Nouveau produit',`<form id="product-form"><div class="form-grid">${formField('Code *','code','text','required')}${formField('Nom *','name','text','required')}${formField('Code-barres','barcode')}${selectField('Fournisseur','supplier_id',s,'id',x=>x.business_name)}${formField('Prix achat','purchase_price','number','min="0" value="0"')}${formField('Prix vente','sale_price','number','min="0" value="0"')}${formField('Stock initial','stock_quantity','number','min="0" step="0.01" value="0"')}${formField('Stock minimum','min_stock','number','min="0" step="0.01" value="0"')}${formField('Unité','unit','text','value="unité"')}<label class="full">Description<textarea name="description"></textarea></label></div>${formActions('Créer')}</form>`);$('#product-form').onsubmit=async e=>{e.preventDefault();try{await api('products',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Produit créé.');renderRoute();}catch(err){toast(err.message,'error')}};}
function openStockAdjust(id){modal('Mouvement de stock',`<form id="stock-form"><div class="form-grid"><label>Type<select name="movement_type"><option value="in">Entrée</option><option value="out">Sortie</option><option value="return">Retour</option><option value="adjustment">Ajustement (+ ou -)</option></select></label>${formField('Quantité *','quantity','number','step="0.01" required')}${formField('Coût unitaire','unit_cost','number','min="0" value="0"')}<label class="full">Motif<textarea name="note" required></textarea></label></div>${formActions('Enregistrer')}</form>`);$('#stock-form').onsubmit=async e=>{e.preventDefault();try{const d=await api(`products/${id}/stock`,{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Nouveau stock : ${fmt.format(d.stock_quantity)}`);renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderSales(){setHead('Ventes','Panier de vente, décrément de stock, facture et encaissement.',actionButton('＋ Nouvelle vente','new-sale','btn primary compact'));const d=await api(`sales?page=${state.page}&size=30`);$('#page').innerHTML=table(['Référence','Date','Client','Total','Payé','Reste','Statut',''],d.items.map(s=>`<tr><td>${esc(s.reference)}</td><td>${dtFr(s.created_at)}</td><td>${esc(clientName(s))}</td><td class="money">${money(s.total)}</td><td class="money">${money(s.paid)}</td><td class="money">${money(s.balance)}</td><td>${badge(s.status==='completed'?'completed':s.status)}</td><td><button class="btn compact" data-sale="${s.id}">Facture</button></td></tr>`),'Aucune vente.')+pager(d);$('#page-actions [data-action="new-sale"]').onclick=openSaleForm;$$('[data-sale]').forEach(b=>b.onclick=()=>printSale(b.dataset.sale));bindPager();}
async function openSaleForm(){const l=await lookups();modal('Nouvelle vente',`<form id="sale-form">${selectField('Client (optionnel)','client_id',l.clients,'id',x=>`${x.last_name} ${x.first_name||''} — ${x.phone||''}`)}<div class="section-title"><h2>Articles</h2><button type="button" class="btn compact" id="add-sale-line">＋ Ligne</button></div><div id="sale-lines"></div><div class="form-grid" style="margin-top:14px">${formField('Remise','discount','number','min="0" value="0"')}${formField('Montant payé','paid','number','min="0" placeholder="Laisser vide = total"')}${selectField('Caisse','cash_account_id',l.accounts,'id',x=>`${x.name} — ${money(x.balance)}`)}<label>Moyen de paiement<select name="payment_method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN</option><option value="moov_money">Moov</option><option value="bank">Banque</option></select></label></div><div class="card soft" style="margin-top:14px">Total panier : <b id="sale-total">0 FCFA</b></div>${formActions('Valider la vente')}</form>`);const lines=$('#sale-lines');const add=()=>{const div=document.createElement('div');div.className='sale-item';div.innerHTML=`<label>Produit<select class="sale-product" required><option value="">— Produit —</option>${l.products.map(p=>`<option value="${p.id}" data-price="${p.sale_price}">${esc(p.name)} — stock ${fmt.format(p.stock_quantity)}</option>`).join('')}</select></label><label>Qté<input class="sale-qty" type="number" min="0.01" step="0.01" value="1" required></label><label>Prix<input class="sale-price" type="number" min="0" value="0" required></label><button type="button" class="icon-btn sale-remove">×</button>`;lines.append(div);const p=$('.sale-product',div),pr=$('.sale-price',div);p.onchange=()=>{pr.value=p.selectedOptions[0]?.dataset.price||0;calc()};$$('input',div).forEach(x=>x.oninput=calc);$('.sale-remove',div).onclick=()=>{div.remove();calc()};};const calc=()=>{let t=0;$$('.sale-item',lines).forEach(r=>t+=Number($('.sale-qty',r).value||0)*Number($('.sale-price',r).value||0));t=Math.max(0,t-Number($('#sale-form').elements.discount.value||0));$('#sale-total').textContent=money(t)};$('#add-sale-line').onclick=add;add();$('#sale-form').elements.discount.oninput=calc;$('#sale-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=objFromForm(f);b.items=$$('.sale-item',lines).map(r=>({product_id:$('.sale-product',r).value,quantity:$('.sale-qty',r).value,unit_price:$('.sale-price',r).value}));if(!b.paid)delete b.paid;try{const d=await api('sales',{method:'POST',body:JSON.stringify(b)});closeModal();toast(`Vente ${d.reference} enregistrée.`);renderRoute();}catch(err){toast(err.message,'error')}};}
async function printSale(id){try{const d=await api(`sales/${id}`),s=d.sale;const settings=(await api('settings')).settings;const html=`<h2>${esc(settings.company_name||'MEGA SERVICES SARL U')}</h2><p>${esc(settings.company_city||'Diabo')} • ${esc(settings.company_phone||'')}</p><hr><h3>FACTURE / VENTE ${esc(s.reference)}</h3><p>Date : ${dtFr(s.created_at)}<br>Client : ${esc(clientName(s))}</p><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;border-bottom:1px solid #999">Article</th><th>Qté</th><th>Prix</th><th>Total</th></tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.description)}</td><td style="text-align:center">${fmt.format(i.quantity)}</td><td style="text-align:right">${money(i.unit_price)}</td><td style="text-align:right">${money(i.total)}</td></tr>`).join('')}</tbody></table><hr><p style="text-align:right"><b>Total : ${money(s.total)}</b><br>Payé : ${money(s.paid)}<br>Reste : ${money(s.balance)}</p>`;printHtml(`Facture ${s.reference}`,html);}catch(err){toast(err.message,'error')}}

async function renderCredits(){setHead('Crédits','Suivi des crédits clients et remboursements sans blocage erroné de solde.',actionButton('＋ Nouveau crédit','new-credit','btn primary compact'));const d=await api(`credits?page=${state.page}&size=30`);$('#page').innerHTML=table(['Référence','Client','Capital','Total dû','Payé','Reste','Échéance','Statut',''],d.items.map(c=>`<tr><td>${esc(c.reference)}</td><td>${esc(clientName(c))}</td><td class="money">${money(c.principal)}</td><td class="money">${money(c.total_due)}</td><td class="money">${money(c.amount_paid)}</td><td class="money">${money(c.balance)}</td><td>${dateFr(c.due_date)}</td><td>${badge(c.status)}</td><td>${['active','late'].includes(c.status)?`<button class="btn compact" data-repay="${c.id}" data-balance="${c.balance}">Rembourser</button>`:''}</td></tr>`),'Aucun crédit.')+pager(d);$('#page-actions [data-action="new-credit"]').onclick=openCreditForm;$$('[data-repay]').forEach(b=>b.onclick=()=>openRepayment(b.dataset.repay,b.dataset.balance));bindPager();}
async function openCreditForm(){const l=await lookups();modal('Nouveau crédit client',`<form id="credit-form"><div class="form-grid">${selectField('Client *','client_id',l.clients,'id',x=>`${x.last_name} ${x.first_name||''} — ${x.phone||''}`,'required')}${formField('Capital *','principal','number','min="1" required')}${formField('Taux (%)','interest_rate','number','min="0" step="0.01" value="0"')}${formField('Frais','fees','number','min="0" value="0"')}${formField('Durée (mois)','duration_months','number','min="1" value="1"')}${formField('Date début','start_date','date',`value="${new Date().toISOString().slice(0,10)}"`)}${formField('Date échéance','due_date','date')}<label class="full">Motif<textarea name="purpose"></textarea></label></div>${formActions('Créer le crédit')}</form>`);$('#credit-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('credits',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Crédit ${d.reference} créé. Dette totale : ${money(d.total_due)}`);renderRoute();}catch(err){toast(err.message,'error')}};}
async function openRepayment(id,balance){const a=(await api('cash/accounts')).items;modal('Remboursement de crédit',`<div class="card soft" style="margin-bottom:14px">Dette restante avant paiement : <b>${money(balance)}</b></div><form id="repay-form"><div class="form-grid">${formField('Montant reçu *','amount','number',`min="1" max="${Number(balance)}" required`)}${selectField('Caisse','cash_account_id',a,'id',x=>`${x.name} — ${money(x.balance)}`)}<label>Moyen de paiement<select name="payment_method"><option value="cash">Espèces</option><option value="wave">Wave</option><option value="orange_money">Orange Money</option><option value="mtn_money">MTN</option><option value="moov_money">Moov</option><option value="bank">Banque</option></select></label><label class="full">Note<textarea name="note"></textarea></label></div><p class="muted">Le remboursement est appliqué directement à la dette restante du crédit.</p>${formActions('Enregistrer le remboursement')}</form>`);$('#repay-form').onsubmit=async e=>{e.preventDefault();try{const d=await api(`credits/${id}/repay`,{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Remboursement enregistré. Nouveau solde : ${money(d.balance)}`);renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderExpenses(){setHead('Dépenses','Charges d’exploitation et sorties de caisse justifiées.',actionButton('＋ Nouvelle dépense','new-expense','btn primary compact'));const d=await api(`expenses?page=${state.page}&size=30`);$('#page').innerHTML=table(['Référence','Date','Catégorie','Description','Caisse','Montant'],d.items.map(x=>`<tr><td>${esc(x.reference)}</td><td>${dateFr(x.expense_date)}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${esc(x.account_name)}</td><td class="money">${money(x.amount)}</td></tr>`),'Aucune dépense.')+pager(d);$('#page-actions [data-action="new-expense"]').onclick=openExpenseForm;bindPager();}
async function openExpenseForm(){const l=await lookups();modal('Nouvelle dépense',`<form id="expense-form"><div class="form-grid"><label>Catégorie<select name="category"><option>Loyer</option><option>Électricité</option><option>Internet</option><option>Transport</option><option>Salaire</option><option>Consommables</option><option>Entretien</option><option>Réparation</option><option>Achat matériel</option><option>Impôts</option><option>Communication</option><option>Autres</option></select></label>${formField('Montant *','amount','number','min="1" required')}${selectField('Caisse *','cash_account_id',l.accounts,'id',x=>`${x.name} — ${money(x.balance)}`,'required')}${selectField('Fournisseur','supplier_id',l.suppliers,'id',x=>x.business_name)}${formField('Date','expense_date','date',`value="${new Date().toISOString().slice(0,10)}"`)}${formField('Référence justificatif','receipt_reference')}<label class="full">Description<textarea name="description" required></textarea></label></div>${formActions('Enregistrer')}</form>`);$('#expense-form').onsubmit=async e=>{e.preventDefault();try{await api('expenses',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Dépense enregistrée.');renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderEmployees(){setHead('Employés','Personnel, matricules et comptes d’accès.',`${actionButton('＋ Employé','new-employee','btn primary compact')} ${actionButton('＋ Compte utilisateur','new-user','btn compact')}`);const e=await api('employees');let users=[];try{users=(await api('users')).items}catch{}$('#page').innerHTML=`${table(['Matricule','Employé','Fonction','Téléphone','Salaire','Statut'],e.items.map(x=>`<tr><td>${esc(x.matricule)}</td><td class="row-title">${esc(x.last_name)} ${esc(x.first_name)}</td><td>${esc(x.function_title||'—')}</td><td>${esc(x.phone||'—')}</td><td class="money">${money(x.salary)}</td><td>${badge(x.status)}</td></tr>`),'Aucun employé.')}<div class="section-title"><h2>Comptes d’accès</h2></div>${table(['Nom','Email','Rôle','Dernière connexion','État'],users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(roleLabels[u.role]||u.role)}</td><td>${dtFr(u.last_login_at)}</td><td>${u.active?badge('active'):badge('cancelled')}</td></tr>`),'Accès réservé à l’administration.')}`;$('#page-actions [data-action="new-employee"]').onclick=openEmployeeForm;$('#page-actions [data-action="new-user"]').onclick=()=>openUserForm(e.items);}
function openEmployeeForm(){modal('Nouvel employé',`<form id="employee-form"><div class="form-grid">${formField('Nom *','last_name','text','required')}${formField('Prénoms *','first_name','text','required')}${formField('Téléphone','phone','tel')}${formField('Email','email','email')}${formField('Fonction','function_title')}${formField('Date embauche','hire_date','date')}${formField('Salaire','salary','number','min="0" value="0"')}</div>${formActions('Créer')}</form>`);$('#employee-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('employees',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast(`Employé créé : ${d.matricule}`);renderRoute();}catch(err){toast(err.message,'error')}};}
function openUserForm(employees){modal('Nouveau compte utilisateur',`<form id="user-form"><div class="form-grid">${selectField('Employé','employee_id',employees,'id',x=>`${x.last_name} ${x.first_name} — ${x.matricule}`)}${formField('Nom affiché *','name','text','required')}${formField('Email *','email','email','required')}${formField('Téléphone','phone','tel')}<label>Rôle<select name="role"><option value="employee">Employé</option><option value="office_agent">Agent bureautique</option><option value="cashier">Caissier</option><option value="mobile_money_agent">Agent Mobile Money</option><option value="sales_agent">Agent commercial</option><option value="stock_manager">Gestionnaire stock</option><option value="accountant">Comptable</option><option value="manager">Responsable</option><option value="admin">Administrateur</option><option value="director">Direction</option></select></label>${formField('Mot de passe initial *','password','password','minlength="10" required')}</div>${formActions('Créer le compte')}</form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();try{await api('users',{method:'POST',body:JSON.stringify(objFromForm(e.target))});closeModal();toast('Compte utilisateur créé.');renderRoute();}catch(err){toast(err.message,'error')}};}

async function renderSuppliers(){setHead('Fournisseurs','Répertoire des fournisseurs et partenaires.',actionButton('＋ Nouveau fournisseur','new-supplier','btn primary compact'));const d=await api('suppliers');$('#page').innerHTML=table(['Référence','Raison sociale','Contact','Téléphone','WhatsApp','Email'],d.items.map(s=>`<tr><td>${esc(s.reference)}</td><td class="row-title">${esc(s.business_name)}</td><td>${esc(s.contact_name||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.whatsapp||'—')}</td><td>${esc(s.email||'—')}</td></tr>`),'Aucun fournisseur.');$('#page-actions [data-action="new-supplier"]').onclick=openSupplierForm;}
