async function renderReports(){setHead('Rapports','Analyse financière et opérationnelle sur une période.','<button class="btn compact" id="export-report">Exporter CSV</button>');const now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),to=now.toISOString().slice(0,10);const d=await api(`reports/summary?from=${from}&to=${to}`);state.cache.report=d;const max=Math.max(1,...d.daily.map(x=>Math.abs(Number(x.net||0))));$('#page').innerHTML=`<div class="toolbar"><label>Du<input id="report-from" type="date" value="${d.from}"></label><label>Au<input id="report-to" type="date" value="${d.to}"></label><button class="btn compact" id="apply-report">Appliquer</button></div><div class="grid cols-4"><div class="card metric dark"><div class="label">Entrées</div><div class="value">${money(d.cash.income)}</div></div><div class="card metric"><div class="label">Dépenses</div><div class="value">${money(d.expenses.amount)}</div></div><div class="card metric"><div class="label">Ventes</div><div class="value">${money(d.sales.total)}</div><div class="sub">${d.sales.count} ventes</div></div><div class="card metric"><div class="label">Créances crédit</div><div class="value">${money(d.credits.outstanding)}</div></div></div><div class="grid cols-2" style="margin-top:16px"><div class="card"><div class="section-title" style="margin-top:0"><h2>Flux net journalier</h2></div><div class="report-bars">${d.daily.length?d.daily.map(x=>`<i class="report-bar" style="height:${Math.max(4,Math.abs(Number(x.net))/max*100)}%" data-tip="${dateFr(x.day)} : ${money(x.net)}"></i>`).join(''):'<span class="muted">Aucun mouvement</span>'}</div></div><div class="card"><div class="section-title" style="margin-top:0"><h2>Services les plus demandés</h2></div>${d.top_services.length?d.top_services.map(x=>`<div class="alert-row"><span>${esc(x.name)}</span><span><b>${fmt.format(x.count)}</b> • ${money(x.total)}</span></div>`).join(''):empty()}</div></div>`;$('#apply-report').onclick=async()=>{const f=$('#report-from').value,t=$('#report-to').value;const r=await api(`reports/summary?from=${f}&to=${t}`);state.cache.report=r;renderReportsData(r)};$('#export-report').onclick=exportReport;}
function renderReportsData(d){const max=Math.max(1,...d.daily.map(x=>Math.abs(Number(x.net||0))));$('#page').innerHTML=`<div class="toolbar"><label>Du<input id="report-from" type="date" value="${d.from}"></label><label>Au<input id="report-to" type="date" value="${d.to}"></label><button class="btn compact" id="apply-report">Appliquer</button></div><div class="grid cols-4"><div class="card metric dark"><div class="label">Entrées</div><div class="value">${money(d.cash.income)}</div></div><div class="card metric"><div class="label">Dépenses</div><div class="value">${money(d.expenses.amount)}</div></div><div class="card metric"><div class="label">Ventes</div><div class="value">${money(d.sales.total)}</div></div><div class="card metric"><div class="label">Créances crédit</div><div class="value">${money(d.credits.outstanding)}</div></div></div><div class="grid cols-2" style="margin-top:16px"><div class="card"><div class="section-title" style="margin-top:0"><h2>Flux net journalier</h2></div><div class="report-bars">${d.daily.map(x=>`<i class="report-bar" style="height:${Math.max(4,Math.abs(Number(x.net))/max*100)}%" data-tip="${dateFr(x.day)} : ${money(x.net)}"></i>`).join('')}</div></div><div class="card">${d.top_services.map(x=>`<div class="alert-row"><span>${esc(x.name)}</span><span><b>${fmt.format(x.count)}</b> • ${money(x.total)}</span></div>`).join('')}</div></div>`;$('#apply-report').onclick=async()=>{const r=await api(`reports/summary?from=${$('#report-from').value}&to=${$('#report-to').value}`);state.cache.report=r;renderReportsData(r)}}
function exportReport(){const d=state.cache.report;if(!d)return;const rows=[['Période',d.from,d.to],['Entrées',d.cash.income],['Dépenses',d.expenses.amount],['Ventes',d.sales.total],['Crédits à recouvrer',d.credits.outstanding],[],['Service','Nombre','Total'],...d.top_services.map(x=>[x.name,x.count,x.total])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`rapport-mega-services-${d.from}-${d.to}.csv`;a.click();URL.revokeObjectURL(a.href);}

async function renderAudit(){setHead('Journal d’activité','Traçabilité des actions sensibles et administratives.');try{const d=await api(`audit?page=${state.page}&size=40`);$('#page').innerHTML=table(['Date','Utilisateur','Action','Entité','Identifiant','IP'],d.items.map(x=>`<tr><td>${dtFr(x.created_at)}</td><td>${esc(x.user_name||'Système')}</td><td class="row-title">${esc(x.action)}</td><td>${esc(x.entity_type||'—')}</td><td>${esc(x.entity_id||'—')}</td><td>${esc(x.ip_address||'—')}</td></tr>`),'Aucune activité auditée.')+pager(d);bindPager();}catch(err){$('#page').innerHTML=`<div class="card empty">${esc(err.message)}</div>`}}

