async function renderHealth(){setHead('Santé système','État des composants Cloudflare utilisés par MSWS.');try{const h=await api('health'),b=await api('bootstrap/status');$('#page').innerHTML=`<div class="grid cols-3"><div class="card metric dark"><div class="label">API</div><div class="value">OK</div><div class="sub">${esc(h.time)}</div></div><div class="card metric"><div class="label">D1 — systeme-d1</div><div class="value">${h.database==='connected'?'Connectée':'À vérifier'}</div><div class="sub">Base centrale</div></div><div class="card metric"><div class="label">KV — systeme_kv</div><div class="value">${h.kv?'Connecté':'À vérifier'}</div><div class="sub">Sessions sécurisées</div></div></div><div class="card" style="margin-top:16px"><h3>Configuration</h3><div class="alert-row"><span>Système initialisé</span><b>${b.initialized?'Oui':'Non'}</b></div><div class="alert-row"><span>Secret BOOTSTRAP_TOKEN configuré</span><b>${b.bootstrap_secret_configured?'Oui':'Non'}</b></div><p class="muted">Les identifiants secrets ne sont jamais affichés dans cette page.</p></div>`;}catch(err){$('#page').innerHTML=`<div class="card empty">${esc(err.message)}</div>`}}

function showQuick(){modal('Nouvelle opération',`<div class="quick-grid"><button class="quick-tile" data-q="client"><span>♙</span>Nouveau client</button><button class="quick-tile" data-q="job"><span>▣</span>Nouveau travail</button><button class="quick-tile" data-q="sale"><span>▧</span>Nouvelle vente</button><button class="quick-tile" data-q="mm"><span>◉</span>Mobile Money</button><button class="quick-tile" data-q="expense"><span>↘</span>Dépense</button><button class="quick-tile" data-q="doc"><span>▤</span>Document</button></div>`);$$('[data-q]').forEach(b=>b.onclick=()=>{closeModal();({client:openClientForm,job:openJobForm,sale:openSaleForm,mm:openMobileForm,expense:openExpenseForm,doc:()=>openDocumentEditor()})[b.dataset.q]?.()});}


